#include <iostream>

class List
{
public:
    List() { m_sentinel.next = m_sentinel.prev = &m_sentinel; }
    ~List() {}
    List(const List&) = delete;
    List& operator=(const List&) = delete;

    void pushBack(int value) {}

private:
    struct Node
    {
        int value{};
        Node* prev{};
        Node* next{};
    };
    Node m_sentinel{};
};

int main()
{
    List l{};
    l.pushBack(1);
}
